import{_ as e,c as p,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"57、【巽】 巽下巽上","description":"周易阐真 - 57、【巽】 巽下巽上","frontmatter":{"title":"57、【巽】 巽下巽上","description":"周易阐真 - 57、【巽】 巽下巽上"},"headers":[],"relativePath":"zh/classics/chanzhen/058.md","filePath":"zh/classics/chanzhen/058.md"}'),s={name:"zh/classics/chanzhen/058.md"};function n(c,a,i,o,h,l){return t(),p("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：重巽以申命。刚巽乎中正而志行。柔皆顺乎刚，是以小亨、利有攸往、利见大人。。</p></blockquote><h1 id="_57、【巽】-巽下巽上" tabindex="-1">57、【巽】 巽下巽上 <a class="header-anchor" href="#_57、【巽】-巽下巽上" aria-label="Permalink to “57、【巽】 巽下巽上”">​</a></h1><p>初六：进退，利武人之贞。</p><p>九二：巽在床下，用史巫纷若，吉，无咎。</p><p>九三：频巽，吝。</p><p>六四：悔亡，田获三品。</p><p>九五：贞吉，悔亡，无不利。无初有终。先庚三日，后庚三日，吉。</p><p>上九：巽在床下，丧其资斧，贞凶。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：随风，巽。君子以申命行事。</p><p>巽者，渐入也，其象为风。上巽风，下巽风，是此风先起，彼风随后，以风随风，巽进之象也。</p><p>君子有见于此，知修道者与人同处，不能无事，既有事不能无行，凡行事须当从容不迫；倘行事急遽，而不与同事者预先申明其所以然，则人不我随，行事不成。以是先申命而后行事焉。申者，申明也；命者，命告也；事者，如修德立业、积功累行、苦己利人之类，凡人所当行者皆是也。命不必拘，为上者申命于下，凡尊长首事者，告示于卑下众人，俱谓命。未行事而先申命，则众人知其事在当行，一人倡前，众人随后，行事未有不成者。亦如风随风，风风相续，并行而不相悖，此君子与人为善之道也。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>巽者，进入也，伏下也，柔顺渐进之谓。巽即为风。卦体一阴伏于二阳之下，以柔道而行刚道，不急不缓，渐次而进，既内巽而又外巽，既下巽而又上巽，由近达远，自卑登高，如风渐吹渐远，渐吹渐高，无处不到，故谓巽。此柔巽进道之卦，承上丰卦而来。丰者，明动合一，曲直应物，潜跃随心，性命由我不由天矣。</p><p>然明动合一之道，岂易成哉！苟非柔巽渐进之功不能。柔巽则耐久，渐进则能入，柔巽渐进，愈久愈力，工夫不缺，终必至于深造自得，是以巽小而有亨道也。但能巽虽是亨道，或知其巽而不能行其巽者有矣；或能巽下，不能巽上者有矣；或能巽上，不能巽下者有矣；或巽于顺，不能巽于逆者有矣；或巽于始，不能巽于终者有矣。凡此皆不能实行巽进之道。巽而不通，求其知行兼能，刚柔并用，能上能下，能顺能逆，能内能外，始终如一之巽，惟具中正之大人能之，是以利有攸往，利见大人也。</p><p>夫大人者，以性命为重，以道德为贵，视幻身如枯木，视富贵如浮云，内常有余，外若不足，真履实践，渐次进步，心坚志远，不到大道完成之后，绝不休歇，故利。若非大人，执于一偏，巽而不中不正，何能有往有利?此有往之利，必归于大人耳。</p><p>初六，柔而无刚，逡畏不力，方进即退，终难深造。然大道人人有分，特患无志耳。果若有志，亲近真师，叩求口诀，勇猛精进，如武人之贞，未有入道不利者。此柔而借刚之巽也。</p><p>九二，刚以柔用，不满不盈，屈己下人，如巽在床下，用史巫纷若，不但治己得吉，而且应人亦无咎。此刚而能柔之巽也。</p><p>九三，自满自盈，有己无人，不能虚心请益，由下而上巽，乃自用聪明，由上而上巽，本欲向前，反成落后，是谓频巽。巽至于频，顺者能巽，逆者不巽，或巽或不巽，适以取吝而已。此刚而不能柔之巽也。</p><p>六四，独柔无刚，似乎柔之太过，不能深造而有悔。然柔之得正，上近五刚，巽顺于上，而得上之济，是获上之一品也。下近三刚，巽顺于下，而得下之济，是获下之一品也。阴居阳中，顺之逆之，皆不失其正，是获中之一品也。上、中、下三品大药，归于中央，阴阳混合，金丹有象，纯是生机，如田中种物，无有不告成者，有何悔之不亡乎?此柔而中正之巽也。</p><p>九五，刚而能巽，惟精推一，允执厥中，是以有悔可亡，而修道无不利矣。其利者，盖以刚而能柔之大人，能下能上，始而巽以自下，似乎用柔伤刚，是无初也。既而巽进于上，反能借柔全刚，是有终也。无初有终之象，如月之先庚三日，后庚三日。先庚三日在于二十八，后庚在于初三。二十八微阳消于艮地，至三十光辉全隐。自二十八至三十，方三日，所谓“先庚三日”也。晦朔之半，月霑日光，阴中藏阳，至初三现蛾眉之光于庚方。自初一至初三，方三日，所谓“后庚三日”也。先庚三日，巽藏其阳；后庚三日，巽进其阳。金丹之道先巽下而深造用其柔，后巽上而自得全其刚。阴中含阳，阳中用阴，大小无伤，至中至正，金丹凝结，刚巽之利，其吉莫大焉。此刚柔两用之巽也。</p><p>上九，在巽之终，巽下之功已毕，柔道宜退，刚道宜进，可以点化群阴之时，不必下巽，须当上巽，居于床上矣。若固执不通，宜在床上者，终在床下。柔过于刚，阴气不化，必至大药得而复失，前功俱废，贞而有凶，可于理决之。此柔过于刚之巽也。</p><p>然则巽进渐入之道，须要识急缓、辨吉凶、知止足，可刚则刚，可柔则柔，随时而用，巽进于刚柔中正为极功也。</p>',23)])])}const m=e(s,[["render",n]]);export{d as __pageData,m as default};
